static void discard_log(void *c,const PAPACC_LOG_RECORD *r){(void)c;(void)r;}
static int load_blob(const char*n,TEST_BLOB*b){PAPACC_TEST_BLOB x={NULL,0};if(!papacc_test_security_load_blob(n,&x))return 0;b->p=x.data;b->n=x.size;return 1;}
static int load_id(const char*c,const char*k,ID*i){PAPACC_TEST_IDENTITY x={ {NULL,0},{NULL,0},NULL};if(!papacc_test_security_load_identity(c,k,&x))return 0;i->cert.p=x.certificate.data;i->cert.n=x.certificate.size;i->key.p=x.private_key.data;i->key.n=x.private_key.size;i->credentials=x.credentials;return 1;}
static void free_id(ID*i){PAPACC_TEST_IDENTITY x={{i->cert.p,i->cert.n},{i->key.p,i->key.n},i->credentials};papacc_test_security_identity_release(&x);memset(i,0,sizeof(*i));}
static PAPACC_U32 client_caps(void){return papacc_test_pst_client_capabilities();}
