static int socket_pair(SOCKET *client,SOCKET *server){SOCKET l=INVALID_SOCKET;struct sockaddr_in a;int n=sizeof(a);*client=*server=INVALID_SOCKET;l=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(l==INVALID_SOCKET)return 0;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(l,(struct sockaddr*)&a,sizeof(a))||listen(l,1)||getsockname(l,(struct sockaddr*)&a,&n))goto fail;*client=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(*client==INVALID_SOCKET||connect(*client,(struct sockaddr*)&a,sizeof(a)))goto fail;*server=accept(l,NULL,NULL);closesocket(l);return *server!=INVALID_SOCKET;fail:if(l!=INVALID_SOCKET)closesocket(l);if(*client!=INVALID_SOCKET)closesocket(*client);return 0;}
